module lamp_assigner(\n    input clk,\n    input rst_n,\n    input start,\n    input [3:0] k,\n    input [31:0] packed_lamp_rows,\n    input [31:0] packed_lamp_cols,\n    output reg result,\n    output reg done\n);\n\n    // Constants\n    localparam [1:0] GRID_SIZE = 4;\n    localparam [1:0] MAX_REACH = 2;\n    localparam [3:0] MAX_LAMPS = 16;\n\n    // States\n    localparam [2:0] IDLE = 3'd0;\n    localparam [2:0] PRECOMPUTE = 3'd1;\n    localparam [2:0] INIT_ASSIGN = 3'd2;\n    localparam [2:0] CHECK_ASSIGN = 3'd3;\n    localparam [2:0] ASSIGN_PASS = 3'd4;\n    localparam [2:0] ASSIGN_FAIL = 3'd5;\n    localparam [2:0] FINISHED = 3'd6;\n\n    // Registers\n    reg [2:0] state;\n    reg [15:0] assignment_counter;\n    reg [15:0] max_assignment;\n    reg [1:0] lamp_rows [0:15];\n    reg [1:0] lamp_cols [0:15];\n    reg [1:0] row_interval_start [0:15];\n    reg [1:0] row_interval_end [0:15];\n    reg [1:0] col_interval_start [0:15];\n    reg [1:0] col_interval_end [0:15];\n\n    // Intermediate storage for checking\n    reg [1:0] row_group_col [0:3][0:3];\n    reg [1:0] row_group_start [0:3][0:3];\n    reg [1:0] row_group_end [0:3][0:3];\n    reg [1:0] row_group_count [0:3];\n    reg [1:0] col_group_row [0:3][0:3];\n    reg [1:0] col_group_start [0:3][0:3];\n    reg [1:0] col_group_end [0:3][0:3];\n    reg [1:0] col_group_count [0:3];\n\n    // Sorting/checking variables\n    reg [2:0] i, j;\n    reg overlap_found;\n\n    // Unpack inputs\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            result <= 1'b0;\n            done <= 1'b0;\n            assignment_counter <= 16'd0;\n            max_assignment <= 16'd0;\n            for (i = 0; i < 16; i = i + 1) begin\n                lamp_rows[i] <= 2'd0;\n                lamp_cols[i] <= 2'd0;\n                row_interval_start[i] <= 2'd0;\n                row_interval_end[i] <= 2'd0;\n                col_interval_start[i] <= 2'd0;\n                col_interval_end[i] <= 2'd0;\n            end\n            for (i = 0; i < 4; i = i + 1) begin\n                row_group_count[i] <= 2'd0;\n                col_group_count[i] <= 2'd0;\n                for (j = 0; j < 4; j = j + 1) begin\n                    row_group_col[i][j] <= 2'd0;\n                    row_group_start[i][j] <= 2'd0;\n                    row_group_end[i][j] <= 2'd0;\n                    col_group_row[i][j] <= 2'd0;\n                    col_group_start[i][j] <= 2'd0;\n                    col_group_end[i][j] <= 2'd0;\n                end\n            end\n            i <= 3'd0;\n            j <= 3'd0;\n            overlap_found <= 1'b0;\n        end else if (start && state == IDLE) begin\n            for (i = 0; i < 16; i = i + 1) begin\n                lamp_rows[i] <= packed_lamp_rows[2*i +: 2];\n                lamp_cols[i] <= packed_lamp_cols[2*i +: 2];\n            end\n            max_assignment <= (1 << k) - 1;\n        end\n    end\n\n    // State machine\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            result <= 1'b0;\n            done <= 1'b0;\n            assignment_counter <= 16'd0;\n        end else begin\n            case (state)\n                IDLE: begin\n                    if (start) begin\n                        state <= PRECOMPUTE;\n                    end\n                end\n                \n                PRECOMPUTE: begin\n                    for (i = 0; i < 16; i = i + 1) begin\n                        row_interval_start[i] <= (lamp_cols[i] >= MAX_REACH) ? lamp_cols[i] - MAX_REACH : 2'd0;\n                        row_interval_end[i] <= (lamp_cols[i] + MAX_REACH < GRID_SIZE) ? lamp_cols[i] + MAX_REACH : GRID_SIZE - 1;\n                        col_interval_start[i] <= (lamp_rows[i] >= MAX_REACH) ? lamp_rows[i] - MAX_REACH : 2'd0;\n                        col_interval_end[i] <= (lamp_rows[i] + MAX_REACH < GRID_SIZE) ? lamp_rows[i] + MAX_REACH : GRID_SIZE - 1;\n                    end\n                    state <= INIT_ASSIGN;\n                end\n                \n                INIT_ASSIGN: begin\n                    assignment_counter <= 16'd0;\n                    state <= CHECK_ASSIGN;\n                end\n                \n                CHECK_ASSIGN: begin\n                    for (i = 0; i < 4; i = i + 1) begin\n                        row_group_count[i] <= 2'd0;\n                        col_group_count[i] <= 2'd0;\n                    end\n                    for (i = 0; i < 16; i = i + 1) begin\n                        if (i < k) begin\n                            if (assignment_counter[i] == 1'b0) begin\n                                row_group_col[lamp_rows[i]][row_group_count[lamp_rows[i]]] <= lamp_cols[i];\n                                row_group_start[lamp_rows[i]][row_group_count[lamp_rows[i]]] <= row_interval_start[i];\n                                row_group_end[lamp_rows[i]][row_group_count[lamp_rows[i]]] <= row_interval_end[i];\n                                row_group_count[lamp_rows[i]] <= row_group_count[lamp_rows[i]] + 1;\n                            end else begin\n                                col_group_row[lamp_cols[i]][col_group_count[lamp_cols[i]]] <= lamp_rows[i];\n                                col_group_start[lamp_cols[i]][col_group_count[lamp_cols[i]]] <= col_interval_start[i];\n                                col_group_end[lamp_cols[i]][col_group_count[lamp_cols[i]]] <= col_interval_end[i];\n                                col_group_count[lamp_cols[i]] <= col_group_count[lamp_cols[i]] + 1;\n                            end\n                        end\n                    end\n                    state <= ASSIGN_PASS;\n                    i <= 3'd0;\n                    j <= 3'd0;\n                    overlap_found <= 1'b0;\n                end\n                \n                ASSIGN_PASS: begin\n                    if (i < 4) begin\n                        if (row_group_count[i] > 1) begin\n                            state <= ASSIGN_FAIL;\n                        end else begin\n                            i <= i + 1;\n                        end\n                    end else begin\n                        i <= 3'd0;\n                        state <= ASSIGN_FAIL;\n                    end\n                end\n                \n                ASSIGN_FAIL: begin\n                    if (!overlap_found && assignment_counter <= max_assignment) begin\n                        result <= 1'b1;\n                        done <= 1'b1;\n                        state <= FINISHED;\n                    end else if (assignment_counter < max_assignment) begin\n                        assignment_counter <= assignment_counter + 1;\n                        state <= CHECK_ASSIGN;\n                    end else begin\n                        result <= 1'b0;\n                        done <= 1'b1;\n                        state <= FINISHED;\n                    end\n                end\n                \n                FINISHED: begin\n                    // Stay in finished state\n                end\n                \n                default: state <= IDLE;\n            endcase\n        end\n    end\n\nendmodule